CREATE TEMP TABLE batch_released_temps (model TEXT NOT NULL, temp TEXT NOT NULL, PRIMARY KEY (model, temp)) WITHOUT ROWID; CREATE TEMP TRIGGER batch_op_release AFTER DELETE ON main.op WHEN OLD.temp_id IS NOT NULL AND OLD.action_key LIKE '%:create' BEGIN INSERT OR IGNORE INTO batch_released_temps VALUES (substr(OLD.action_key, 1, instr(OLD.action_key, ':') - 1), OLD.temp_id); END; CREATE TEMP TRIGGER batch_upload_release AFTER DELETE ON main.sync_upload WHEN NOT ({flag}) BEGIN INSERT OR IGNORE INTO batch_released_temps VALUES (OLD.model, OLD.row_id); END;